using SemanticContracts; using SemanticQueries.Core; namespace Packages.BoundsBridge; public sealed class BoundsBridgeProvider:IQueryProvider<InBoundsKey,Proof>{private static readonly RangeQuery R=new();private static readonly LengthQuery L=new();public QueryResult<Proof> TryGet(InBoundsKey key,QueryContext c){var r=c.Query(R,new(key.Index,key.Point));var l=c.Query(L,new(key.Array,key.Point));if(r.Status!=QueryStatus.Known||l.Status!=QueryStatus.Known)return QueryResult<Proof>.Unknown;return r.Value!.Lower>=0&&r.Value.Upper<l.Value?QueryResult<Proof>.Known(Proof.Yes):QueryResult<Proof>.Unknown;}}